package cat.urysoft.widgets;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
import java.io.*;import java.time.Duration;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w1080dp-h1920dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class WidgetRowSurfaceTest {
 private Context c=RuntimeEnvironment.getApplication();
 private WidgetConfig config(int n){WidgetConfig v=new WidgetConfig();Class<?>[] classes={MainActivity.class,OptionsActivity.class,ConfigureActivity.class,PremiumActivity.class,LaunchActivity.class};for(int i=0;i<n;i++)v.apps.add(i<5?new ComponentName(c,classes[i]).flattenToString():"example.app"+i+"/.Main");v.columns=5;v.labels=false;v.badges=false;v.heading=true;v.name="UrySoft";v.editButton=false;v.opacity=100;v.background=Color.BLACK;v.shadowEnabled=true;v.shadowOpacity=100;v.shadowColor=0xffff00ff;v.shadowSharpness=100;v.shadowDistance=16;return v;}
 private static void measure(View v,int w,int h){for(int i=0;i<3;i++){v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);}}
 @Test public void fullLauncherGridPreservesAllEightShadowDirectionsAndEveryTouch()throws Exception{
  try(ActivityController<Activity> window=Robolectric.buildActivity(Activity.class).setup().visible()){
   for(int angle=0;angle<360;angle+=45){WidgetConfig v=config(5);v.shadowAngle=angle;ConfigStore.put(c,901,v);
    AppWidgetHostView host=new AppWidgetHostView(window.get());View root=WidgetRenderer.build(c,901,v,960,430).apply(c,host);host.addView(root);window.get().setContentView(host);measure(root,960,430);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(250));measure(root,960,430);
    GridView grid=root.findViewById(R.id.widget_grid);assertNotNull(grid.getAdapter());assertEquals(1,grid.getAdapter().getCount());View row=grid.getChildAt(0);assertNotNull(row);
    ImageView surface=row.findViewById(R.id.row_surface);assertEquals(960,surface.getWidth());assertEquals(0,surface.getPaddingBottom());
    Bitmap actual=Bitmap.createBitmap(960,430,Bitmap.Config.ARGB_8888);root.draw(new Canvas(actual));WidgetConfig resolved=WidgetRenderer.resolve(c,v,960,430);Bitmap strip=RowRenderer.render(c,resolved,0);
    int[] p=new int[2];surface.getLocationOnScreen(p);int[] rp=new int[2];root.getLocationOnScreen(rp);int left=p[0]-rp[0],top=p[1]-rp[1];Bitmap expected=Bitmap.createBitmap(surface.getWidth(),surface.getHeight(),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(expected);canvas.drawColor(Color.BLACK);canvas.drawBitmap(strip,null,new Rect(0,0,expected.getWidth(),expected.getHeight()),null);
    int shadow=0,mismatch=0;for(int y=0;y<expected.getHeight();y++)for(int x=0;x<expected.getWidth();x++){int color=expected.getPixel(x,y);if(Color.red(color)>160&&Color.blue(color)>160&&Color.green(color)<60){shadow++;if(actual.getPixel(left+x,top+y)!=color)mismatch++;}}
    assertTrue("Reference has a visible shadow at "+angle,shadow>100);assertEquals("Full GridView must preserve shadow pixels at "+angle,0,mismatch);
    String dir=System.getProperty("ury.qa.dir");if(dir!=null){new File(dir).mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"widget-row-shadow-"+angle+".png"))){actual.compress(Bitmap.CompressFormat.PNG,100,out);}}
    if(angle==90){LinearLayout actions=row.findViewById(R.id.row_actions);assertEquals(8,actions.getChildCount());for(int i=0;i<5;i++){assertEquals(Math.round(resolved.cellWidthDp)+(i==4?0:resolved.columnGapDp),actions.getChildAt(i).getWidth());assertTrue(actions.getChildAt(i).performClick());Intent intent=Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedActivity();assertNotNull(intent);assertEquals(v.apps.get(i),intent.getStringExtra("component"));}}
   }
  }
 }
 @Test public void realContactTapAndScrollingWorkInTheLauncher()throws Exception{
  ContactFeaturesTest.FakeContacts provider=new ContactFeaturesTest.FakeContacts();provider.advertisePhoto=true;provider.directOnly=true;android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority=android.provider.ContactsContract.AUTHORITY;provider.attachInfo(c,info);org.robolectric.shadows.ShadowContentResolver.registerProviderInternal(info.authority,provider);
  provider.photo=new File(c.getCacheDir(),"row-contact.png");Bitmap photo=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);photo.eraseColor(0xffe43d58);try(FileOutputStream out=new FileOutputStream(provider.photo)){photo.compress(Bitmap.CompressFormat.PNG,100,out);}ContactStore.Entry contact=ContactStore.importSelected(c,ContactFeaturesTest.SELECTED);
  WidgetConfig v=config(1);v.apps.add(contact.id);v.columns=2;v.shadowEnabled=false;assertTrue(ConfigStore.put(c,902,v));
  try(ActivityController<Activity> window=Robolectric.buildActivity(Activity.class).setup().visible()){
   AppWidgetHostView host=new AppWidgetHostView(window.get());View root=WidgetRenderer.build(c,902,v,360,240).apply(c,host);host.addView(root);window.get().setContentView(host);measure(root,360,240);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(250));measure(root,360,240);GridView grid=root.findViewById(R.id.widget_grid);View row=grid.getChildAt(0);View hit=row.findViewById(R.id.row_hit_1);int[] hp=new int[2],gp=new int[2];hit.getLocationOnScreen(hp);grid.getLocationOnScreen(gp);float x=hp[0]-gp[0]+hit.getWidth()/2f,y=hp[1]-gp[1]+hit.getHeight()/2f;long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(now,now+80,MotionEvent.ACTION_UP,x,y,0);grid.dispatchTouchEvent(down);grid.dispatchTouchEvent(up);down.recycle();up.recycle();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(500));Intent intent=Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedActivity();assertNotNull(intent);assertEquals(contact.id,intent.getStringExtra("component"));try(ActivityController<LaunchActivity> launch=Robolectric.buildActivity(LaunchActivity.class,intent).create()){Intent target=Shadows.shadowOf(launch.get()).getNextStartedActivity();assertNotNull(target);assertEquals(Intent.ACTION_VIEW,target.getAction());assertEquals(contact.uri,target.getData());}
   v=config(17);root=WidgetRenderer.build(c,903,v,360,180).apply(c,host);host.removeAllViews();host.addView(root);measure(root,360,180);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(250));measure(root,360,180);grid=root.findViewById(R.id.widget_grid);assertEquals(4,grid.getAdapter().getCount());grid.scrollListBy(10000);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(250));measure(root,360,180);assertEquals(3,grid.getLastVisiblePosition());
  }
 }
 @Test public void multipleRowsHaveContinuousShadowsAndScrollWithoutLosingEntries(){WidgetConfig v=config(17);WidgetConfig r=WidgetRenderer.resolve(c,v,360,180);assertEquals(4,RowRenderer.count(r));assertEquals(0,r.gridInsetTopPx);for(int row=0;row<RowRenderer.count(r);row++){View view=WidgetRenderer.row(c,r,row).apply(c,new FrameLayout(c));measure(view,360,Math.round(RowRenderer.height(c,r,row)));assertNotNull(view.findViewById(R.id.row_surface));assertEquals(8,((LinearLayout)view.findViewById(R.id.row_actions)).getChildCount());}assertEquals(0,new WidgetConfig().shadowOutsetDp);}
}
